// newInput builds the insert a Batch queues for in, and
// the record it stands for, named: the same resolution Create applies.
func (r *GraphQLTransientRfpRepository) newInput(in *transient_rfpv1.TransientRfp) (resourceql.CreateInput, *transient_rfpv1.TransientRfp, error) {
	var ci resourceql.CreateInput
	id := repox.NewULID()
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "transientRfps")
		if err != nil {
			return ci, nil, err
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*transient_rfpv1.TransientRfp)
	in.Name = FormatTransientRfpName(id)
	ci = transientRfpToCreateInput(in)
	ci.Id = id
	ci.Etag = repox.NewULID()
	now := tsToStr(timestamppb.New(time.Now().UTC()))
	ci.CreateTime = now
	ci.UpdateTime = now
	return ci, in, nil
}

