// UpdateOutputOnly persists the server-owned fields of in that paths names.
// When in.Etag is set the write is guarded server-side, as in Update.
func (r *GraphQLTransientRfpRepository) UpdateOutputOnly(ctx context.Context, in *transient_rfpv1.TransientRfp, paths []string) (*transient_rfpv1.TransientRfp, error) {
	if len(paths) == 0 {
		return nil, fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument)
	}
	id, err := r.rowID(ctx, in.GetName())
	if err != nil {
		return nil, err
	}
	patch := transientRfpToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	if in.GetEtag() != "" {
		if _, err := r.Svc.Mutation.Transientrfp.Resource.UpdateIfMatch(ctx, id, patch, resourceql.Etag.Eq(in.GetEtag())); err != nil {
			return nil, mapGraphQLErr(err)
		}
		return r.get(ctx, id)
	}
	resp, err := r.Svc.Mutation.Transientrfp.Resource.Update(ctx, id, patch)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return nil, repox.ErrNotFound
	}
	return r.get(ctx, id)
}

// Delete soft-deletes the record addressed by its resource name: delete_time
// is set, the row stays. The update time is set to the same instant: the
// delete is the record's latest write, which a reader by update time can tell
// from any write after it.
func (r *GraphQLTransientRfpRepository) Delete(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "transientRfps"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	if _, err := r.Svc.Mutation.Transientrfp.Resource.UpdateIfMatch(ctx, id, r.deletePatch(), resourceql.DeleteTime.IsNull(true)); err != nil {
		if errors.Is(err, graphql.ErrConflict) {
			return repox.ErrNotFound
		}
		return mapGraphQLErr(err)
	}
	return nil
}

// deletePatch is the write that soft-deletes a record now: Delete's, and a
// Batch's.
func (r *GraphQLTransientRfpRepository) deletePatch() resourceql.UpdateInput {
	at := time.Now().UTC()
	now := at.Format(time.RFC3339Nano)
	patch := resourceql.UpdateInput{DeleteTime: graphql.Value(now)}
	patch.UpdateTime = graphql.Value(now) // the delete is the record's latest write
	if r.Retention > 0 {
		patch.ExpireTime = graphql.Value(at.Add(r.Retention).Format(time.RFC3339Nano))
	}
	patch.Etag = graphql.Value(repox.NewULID())
	return patch
}

// Undelete clears the soft-delete mark and returns the restored record.
func (r *GraphQLTransientRfpRepository) Undelete(ctx context.Context, name string) (*transient_rfpv1.TransientRfp, error) {
	id, err := r.rowID(ctx, name)
	if err != nil {
		return nil, err
	}
	patch := resourceql.UpdateInput{DeleteTime: graphql.Null[string]()}
	patch.UpdateTime = graphql.Value(time.Now().UTC().Format(time.RFC3339Nano))
	patch.ExpireTime = graphql.Null[string]()
	patch.Etag = graphql.Value(repox.NewULID())
	if _, err := r.Svc.Mutation.Transientrfp.Resource.UpdateIfMatch(ctx, id, patch, resourceql.DeleteTime.IsNull(false)); err != nil {
		if !errors.Is(err, graphql.ErrConflict) {
			return nil, mapGraphQLErr(err)
		}
		if _, err := r.get(ctx, id); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("%w: %s is not deleted", repox.ErrAlreadyExists, name)
	}
	return r.get(ctx, id)
}

// Purge removes the record addressed by its resource name for good.
func (r *GraphQLTransientRfpRepository) Purge(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "transientRfps"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	_, err = r.purge(ctx, id, name, true)
	return err
}

// purge removes row id, named name, for good -- unless something still
// refers to it, when it keeps the row and reports kept: when askReferrers, a
// referrer in another database or service (r.Refs), and, caught from the
// database's own refusal, a row holding a foreign key to it. A purge never
// fails, and never cascades, because of a referrer. repox.ErrNotFound when
// there is no such row.
func (r *GraphQLTransientRfpRepository) purge(ctx context.Context, id, name string, askReferrers bool) (kept bool, err error) {
	if askReferrers && r.Refs.KeepOnPurge(ctx, "hotel.opentravel.org/TransientRfp", name) {
		return true, nil
	}
	err = r.remove(ctx, id)
	if repox.IsForeignKeyViolation(err) {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	return false, err
}

// PurgeExpired removes for good every deleted record whose expire_time is at
// or before now, keeping the ones something still refers to (see purge).
// Hooks do not run.
func (r *GraphQLTransientRfpRepository) PurgeExpired(ctx context.Context, now time.Time) (repox.PurgeResult, error) {
	var res repox.PurgeResult
	in := repox.ListInput{
		PageSize:    500,
		ShowDeleted: true,
		ReadMask:    []string{"name"},
		Where: []filterx.Condition{
			{Field: "delete_time", Op: filterx.OpNull, Value: "false"},
			{Field: "expire_time", Op: filterx.OpLte, Value: now.UTC().Format(time.RFC3339Nano)},
		},
	}
	for {
		page, next, err := r.list(ctx, in)
		if err != nil {
			return res, err
		}
		for _, m := range page {
			id, err := r.rowID(ctx, m.GetName())
			if errors.Is(err, repox.ErrNotFound) {
				continue // gone since the page was read
			}
			if err != nil {
				return res, err
			}
			kept, err := r.purge(ctx, id, m.GetName(), true)
			switch {
			case errors.Is(err, repox.ErrNotFound):
			case err != nil:
				return res, err
			case kept:
				res.Kept = append(res.Kept, m.GetName())
			default:
				res.Purged = append(res.Purged, m.GetName())
			}
		}
		if next == "" {
			return res, nil
		}
		in.PageToken = next
	}
}

// remove deletes row id with the value-object rows it owns.
func (r *GraphQLTransientRfpRepository) remove(ctx context.Context, id string) error {
	resp, err := r.Svc.Mutation.Transientrfp.Resource.Delete(ctx, id)
	if err != nil {
		return mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return repox.ErrNotFound
	}
	for i := range resp.Returning {
		if id := repox.Deref(resp.Returning[i].AccountSpecificInfoId); id != "" {
			if _, err := r.Svc.Mutation.Transientrfp.AccountSpecificInfos.Delete(ctx, id); err != nil {
				return mapGraphQLErr(err)
			}
		}
	}
	dtx := r.Svc.Mutation.Tx()
	for i := range resp.Returning {
		if id := repox.Deref(resp.Returning[i].HotelAddressId); id != "" {
			got21, err := r.Svc.Query.Transientrfp.AddressPrefs.Get(ctx, id)
			if err != nil {
				return mapGraphQLErr(err)
			}
			if got21 != nil {
				dtx.Add(r.Svc.Mutation.Transientrfp.AddressPrefs.DeleteOp(got21.Id, new(addressprefsql.DeleteTransientrfpAddressPrefsByIdResponse)))
				if id := got21.AddressId; id != "" {
					got22, err := r.Svc.Query.Transientrfp.AddressInfos.Get(ctx, id)
					if err != nil {
						return mapGraphQLErr(err)
					}
					if got22 != nil {
						dtx.Add(r.Svc.Mutation.Transientrfp.AddressInfos.DeleteOp(got22.Id, new(addressinfosql.DeleteTransientrfpAddressInfosByIdResponse)))
						if id := repox.Deref(got22.StreetNmbrId); id != "" {
							got23, err := r.Svc.Query.Transientrfp.StreetNmbrs.Get(ctx, id)
							if err != nil {
								return mapGraphQLErr(err)
							}
							if got23 != nil {
								dtx.Add(r.Svc.Mutation.Transientrfp.StreetNmbrs.DeleteOp(got23.Id, new(streetnmbrsql.DeleteTransientrfpStreetNmbrsByIdResponse)))
							}
						}
						if id := repox.Deref(got22.StateProvId); id != "" {
							got24, err := r.Svc.Query.Transientrfp.StateProvs.Get(ctx, id)
							if err != nil {
								return mapGraphQLErr(err)
							}
							if got24 != nil {
								dtx.Add(r.Svc.Mutation.Transientrfp.StateProvs.DeleteOp(got24.Id, new(stateprovsql.DeleteTransientrfpStateProvsByIdResponse)))
							}
						}
						if id := repox.Deref(got22.CountryDisplayNameId); id != "" {
							got25, err := r.Svc.Query.Transientrfp.CountryNames.Get(ctx, id)
							if err != nil {
								return mapGraphQLErr(err)
							}
							if got25 != nil {
								dtx.Add(r.Svc.Mutation.Transientrfp.CountryNames.DeleteOp(got25.Id, new(countrynamesql.DeleteTransientrfpCountryNamesByIdResponse)))
							}
						}
					}
				}
			}
		}
	}
	{
		rows39, err := r.Svc.Query.Transientrfp.ContactInfoRoots.List(ctx, contactinforootsql.List().Where(contactinforootsql.TransientRfpId.Eq(id)))
		if err != nil {
			return mapGraphQLErr(err)
		}
		for i := range rows39 {
			if id := rows39[i].Id; id != "" {
				got40, err := r.Svc.Query.Transientrfp.ContactInfoRoots.Get(ctx, id)
				if err != nil {
					return mapGraphQLErr(err)
				}
				if got40 != nil {
					dtx.Add(r.Svc.Mutation.Transientrfp.ContactInfoRoots.DeleteOp(got40.Id, new(contactinforootsql.DeleteTransientrfpContactInfoRootsByIdResponse)))
					_ = repox.Deref(got40.CompanyDisplayNameId)
				}
			}
		}
	}
	if err := dtx.Commit(ctx); err != nil {
		return mapGraphQLErr(err)
	}
	return nil
}

